INSERT OR IGNORE INTO our_team (id, source_application_id, source_application_type, name, role, bio, image_url, display_at_team, created_at, updated_at) VALUES
('ot_orig_mithra', NULL, 'original', 'Mithra Venkatesan', 'Founder, Program Coordinator, Tutor', 'Mithra is a junior at South Lakes High School in Herndon, Virginia. She is a gymnast, cheerleader, tennis player, and aspires to pursue a career in medicine. Mithra had the unique privilege of studying for a few years in Tamil Nadu during her formative years, so she is naturally well-versed in the Tamil language and culture.\n\nWitnessing firsthand the economic and educational doors that English fluency opened for her peers, especially in rural areas, instilled in her a deep understanding of the need for bilingualism and a sense of responsibility to the underprivileged by starting Seeds of Success.', 'Images/Mithra_Pic.avif', 1, '2024-01-01T00:00:00Z', '2024-01-01T00:00:00Z'),
('ot_orig_nila', NULL, 'original', 'Nila Loganathan', 'Founder, Program Coordinator, Tutor', 'Nila is a rising sophomore at Freedom High School in Chantilly, Virginia. She is a dedicated gymnast and is notably fluent in Tamil, possessing strong skills in speaking, reading, and writing the language. Nila particularly excels at public speaking in both Tamil and English, a skill she uses to connect with and motivate students.\n\nThe opportunity to work with and assist underprivileged students is what motivated her to co-start Seeds of Success. Nila recognizes the program''s meaningful cause and is confident her involvement will positively impact the kids while maximizing the program''s reach.', 'Images/Nila_pic.avif', 1, '2024-01-02T00:00:00Z', '2024-01-02T00:00:00Z'),
('ot_orig_kavin', NULL, 'original', 'Kavin Loganathan', 'Founder, Technology Innovator', 'Kavin is an eighth-grader at J. Michael Lunsford Middle School in Chantilly, Virginia. He is a well-versed debater, an enthusiastic public speaker, and an athlete who plays lacrosse and volleyball. As an avid technologist who enjoys solving complex problems, Kavin has taken on the vital role of providing technological support for Seeds of Success.\n\nHis responsibilities include building and maintaining the organization''s digital solutions. Furthermore, he plays a key part in digitalizing the curriculum and ensuring the technical framework is in place to help the organization scale its operations and reach.', 'Images/Kavin_Pic.avif', 1, '2024-01-03T00:00:00Z', '2024-01-03T00:00:00Z'),
('ot_orig_prakash', NULL, 'original', 'Prakash Swaminathan', 'Curriculum Developer, Tutor', NULL, 'Images/Prakash.avif', 1, '2024-01-04T00:00:00Z', '2024-01-04T00:00:00Z'),
('ot_orig_thangamani', NULL, 'original', 'Thangamani R.', 'Curriculum Developer', NULL, 'Images/SeedsOfSuccess_pic.jpeg', 1, '2024-01-05T00:00:00Z', '2024-01-05T00:00:00Z'),
('ot_orig_ananya', NULL, 'original', 'Ananya Rajasekaran', 'Tutor', NULL, 'Images/Ananya_Pic.avif', 1, '2024-01-06T00:00:00Z', '2024-01-06T00:00:00Z'),
('ot_orig_abhimanyuu', NULL, 'original', 'Abhimanyuu Rajkumar', 'Digital Learning & Social Media Coordinator', 'Abhimanyuu Rajkumar is a 9th grader at Oakton High School in Vienna, Virginia, and lives in Herndon, Virginia. He is a skilled technology enthusiast, a dedicated student, and a competitive athlete who plays both baseball and basketball. Passionate about making a meaningful difference in the lives of others, he took the initiative to join Seeds of Success as the organization''s Social Media Coordinator, where he combines his creativity and technical skills to expand the organization''s reach and impact.\n\nAs the Social Media Coordinator, he is responsible for creating engaging posters, videos, and other digital content that promote the organization''s mission and fundraising efforts. He also ensures that supporters have the information they need to get involved, whether through volunteering, donating, or spreading awareness. Through strategic communication and creative outreach, he helps connect more people with the mission of Seeds of Success and supports the organization''s continued growth.', 'Images/Abhimanyuu Rajkumar_Pic.jpeg', 1, '2024-01-07T00:00:00Z', '2024-01-07T00:00:00Z'),
('ot_orig_praneetha', NULL, 'original', 'Praneetha', 'Tutor', 'Praneetha is a rising sophomore at John Champe High School in Aldie, Virginia. Outside of school in her own time she involves herself in activies such as swim, and runs our own nail business from home. She has been a fluent tamil speaker since birth, and overtime has improved her writing and reading skills.\n\nWith her variety of skills she is very much involved in her community helping in ways she can. To extend her aid across the globe she grabbed on the opportunity to participate in Seeds of Sucess. Praneetha appreciates and is thrilled to be a part of a community that has such a meaningful impact on eager individuals who want to grow their skills', 'Images/Praneetha.png', 1, '2024-01-08T00:00:00Z', '2024-01-08T00:00:00Z'),
('ot_orig_dhanyashree', NULL, 'original', 'Dhanyashree Dineshkumar', 'Tutor', 'Dhanyashree is an incoming freshman at Skyview High School in Herndon, Virginia. Outside of school, music plays a huge role in her life, where she enjoys singing, playing the guitar, and playing a traditional instrument called the veena. She is also a fluent speaker in both Tamil and English.\n\nDhanyashree is excited to join Seeds of Success and teach English to kids who are learning the language. She looks forward to helping her students build a key skill that will support them for years to come.', 'Images/Dhanyashree_Pic.jpeg', 1, '2024-01-09T00:00:00Z', '2024-01-09T00:00:00Z'),
('ot_orig_thara', NULL, 'original', 'Thara Venkatesan', 'Tutor', 'Thara is a second-year student at the College of William & Mary in Williamsburg, Virginia. She serves as the key mentor to Seeds of Success founders. Drawing on her own leadership experience, she provides guidance and strategic support to the emerging organization.\n\nHaving attended Tamil school for 12 years, she is fluent in the language and proficient in speaking, reading, and writing. With a passion for teaching children and a goal to teach English abroad, she is excited to give back to her community of origin and help guide the next generation of program leaders.', 'Images/Thara_Pic.avif', 1, '2024-01-10T00:00:00Z', '2024-01-10T00:00:00Z'),
('ot_orig_kayal', NULL, 'original', 'Kayal Sadasivam', 'Tutor', NULL, 'Images/Kayal_Pic.avif', 1, '2024-01-11T00:00:00Z', '2024-01-11T00:00:00Z'),
('ot_orig_senthiru', NULL, 'original', 'Senthiru Priya. B', 'Tutor', NULL, 'Images/Senthiru_Pic.avif', 1, '2024-01-12T00:00:00Z', '2024-01-12T00:00:00Z'),
('ot_orig_vasanthi', NULL, 'original', 'Vasanthi Sekar', 'Tutor', NULL, 'Images/Vasanthi_Pic.avif', 1, '2024-01-13T00:00:00Z', '2024-01-13T00:00:00Z');
